from openpyxl import load_workbook

wb=load_workbook('/root/output/rar_result.xlsx')
ws=wb['Gold price']
last_row=ws.max_row
for r in range(2, last_row+1):
    # update D/E formulas if present
    if ws[f'D{r}'].value and isinstance(ws[f'D{r}'].value, str) and 'STDEV.S' in ws[f'D{r}'].value.upper():
        ws[f'D{r}'].value = ws[f'D{r}'].value.upper().replace('STDEV.S','STDEV')
    if ws[f'E{r}'].value and isinstance(ws[f'E{r}'].value, str) and 'STDEV.S' in ws[f'E{r}'].value.upper():
        ws[f'E{r}'].value = ws[f'E{r}'].value.upper().replace('STDEV.S','STDEV')

wb.save('/root/output/rar_result.xlsx')
